const s = sdk.getState();
return {
  pos: s && { x: s.player.worldX, z: s.player.worldZ },
  hp: s?.player.currentHp,
  combat: s?.player.combatLevel,
  skills: s?.skills?.filter(sk => ['Attack','Strength','Defence','Hitpoints'].includes(sk.name)).map(sk => `${sk.name}:${sk.baseLevel}`),
  npcs: s?.nearbyNpcs?.slice(0, 40).map(n => `${n.name}(${n.combatLevel}) d=${n.distance}${n.inCombat?' [fight]':''}${n.reachable===false?' [unreach]':''}`),
  inventory: s?.inventory?.map(i => i?.name).filter(Boolean),
};

const killed: string[] = [];
const deadline = Date.now() + 150_000; // ~2.5 min phase

async function killOne(pattern: RegExp, maxMs = 45000): Promise<boolean> {
  const end = Date.now() + maxMs;
  while (Date.now() < end && Date.now() < deadline) {
    await bot.dismissBlockingUI();
    const npc = sdk.findNearbyNpc(pattern, { reachable: true } as any) ?? sdk.findNearbyNpc(pattern);
    if (!npc) return false;
    try {
      const r = await bot.attack(npc, 5000);
      if (r.success) {
        // wait for fight to end
        await sdk.waitForCondition(s => s && s.player && !s.player.combat.inCombat, 25000);
        await sdk.waitForTicks(1);
        const after = sdk.getState();
        const stillThere = after?.nearbyNpcs?.some(n => n.index === npc.index);
        if (!stillThere || (after?.player?.currentHp ?? 10) < 10 || true) {
          // target gone => died; if I'm alive, credit likely mine (solo)
          if (after?.player && after.player.currentHp > 0) return true;
          return false;
        }
      } else {
        // reason handling: already_in_combat -> try another, unreachable -> false
        if (r.reason === 'out_of_reach' || r.reason === 'npc_not_found') return false;
        if (r.reason === 'already_in_combat') {
          await sdk.waitForTicks(10 + Math.floor(Math.random() * 20));
          continue;
        }
        await sdk.waitForTicks(5);
      }
    } catch (e) {
      console.log('attack err', e);
      await sdk.waitForTicks(5);
    }
  }
  return false;
}

const plan: [RegExp, string][] = [
  [/^rat$/i, 'Rat'],
  [/^man$/i, 'Man'],
  [/^woman$/i, 'Woman'],
];

for (const [pat, name] of plan) {
  if (Date.now() >= deadline) break;
  const already = killed.includes(name);
  if (already) continue;
  console.log('Hunting', name);
  const ok = await killOne(pat);
  console.log(name, ok ? 'KILLED' : 'failed');
  if (ok) killed.push(name);
}

const s = sdk.getState();
return {
  killed,
  pos: s && [s.player.worldX, s.player.worldZ],
  hp: s?.player.currentHp,
  combatLvl: s?.player.combatLevel,
  xp: s?.skills?.filter(sk => ['Attack','Strength','Defence','Hitpoints'].includes(sk.name)).map(sk => `${sk.name}:${sk.baseLevel}/${sk.xp}`),
};

